class SettingsCheckpoint78 {
 @get:Rule(order=0) val locale:TestRule=QaAppLocaleRule()
 @get:Rule(order=1) val compose=createEmptyComposeRule()
 private val f=InvitationUiFixture(compose)
 private val out get()=File(checkNotNull(InstrumentationRegistry.getArguments().getString("additionalTestOutputDir")))
 private val actions=JSONArray();private val result=JSONObject()
 private fun hideKeyboard(){if(f.device.hasObject(By.pkg(Pattern.compile(".*inputmethod.*")))){f.device.pressBack();Thread.sleep(200)}}
 private fun log(s:String){actions.put(JSONObject().put("action",s).put("at",Instant.now().toString()))}
 @Before fun setup(){f.configure();out.mkdirs()}
 private fun capture(name:String){f.screenshot(name);File(out,"$name.semantics.txt").writeText(compose.onAllNodes(isRoot(),useUnmergedTree=true).printToString(maxDepth=100));File(out,"actions.json").writeText(actions.toString(2))}
 private fun open(id:String){f.waitTag("meetings-list");compose.onNodeWithTag("meetings-list").performScrollToNode(hasTestTag("meeting-$id"));compose.onNodeWithTag("meeting-$id").performClick();f.waitTag("invitation-conversation");compose.onNodeWithContentDescription("Информация о встрече").performClick();f.waitTag("meeting-information");compose.onNodeWithTag("open-settings").performScrollTo().performClick();f.waitTag("meeting-settings")}
 private fun role(s:String,body:()->Unit){f.launch(s).use{try{body()}catch(e:Throwable){runCatching{capture("failure-live")};throw e}}}
 @Test fun settingsShort(){try{
  role("cover-edit"){
   open("c0fe0000-0000-4000-8000-000000000100");f.waitTag("meeting-cover");log("Organizer normal360: real cover card, required legend/fields, pinned action");capture("settings360-cover")
   compose.onNodeWithContentDescription("Название").performTextReplacement("");compose.onNodeWithContentDescription("Описание").performScrollTo().performTextInput("Проверка обязательного названия");compose.onNodeWithTag("settings-save").performClick();f.waitText("Название должно содержать от 1 до 120 символов.");capture("required-error-ime");val focus=compose.onNodeWithContentDescription("Название").fetchSemanticsNode().config.getOrNull(SemanticsProperties.Focused);result.put("titleFocusedAfterInvalidSave",focus==true);log("Invalid save: title hint exists; title focused=$focus (record actual, continue independent checks)")
   compose.onNodeWithContentDescription("Название").performScrollTo().performTextReplacement("Несохранённая правка");f.device.pressBack();f.shell("wm size 640x1280");Thread.sleep(400);compose.onNodeWithContentDescription("Описание").performScrollTo().performTextInput(" Ещё строка");compose.onNodeWithTag("settings-save").assertIsDisplayed();capture("settings320-ime");log("320dp real IME: fields and sticky save reachable");f.device.pressBack();f.shell("wm size reset");Thread.sleep(300);hideKeyboard()
   hideKeyboard();f.device.pressBack();f.waitText("Закрыть настройки?");compose.onAllNodesWithTag("chat-action-sheet").assertCountEquals(1);capture("dirty-confirm");compose.onNodeWithText("Продолжить редактирование").performClick();f.waitTag("settings-save");compose.onNodeWithContentDescription("Название").assertTextContains("Несохранённая правка");log("Dirty Back -> stay keeps same panel and values");hideKeyboard();f.device.pressBack();f.waitText("Закрыть настройки?");compose.onNodeWithText("Закрыть без сохранения").performClick();f.waitTag("meeting-information");compose.onNodeWithText("Встреча с фото",useUnmergedTree=true).assertExists();log("Dirty Back -> leave returns original info without saving")
   compose.onNodeWithTag("open-settings").performScrollTo().performClick();f.waitTag("settings-save");compose.onNodeWithContentDescription("Название").performScrollTo().performTextReplacement("Встреча после правки");f.device.pressBack();compose.onNodeWithTag("settings-save").performClick();f.waitTag("meeting-information");f.waitText("Изменения сохранены");compose.onNodeWithText("Встреча после правки",useUnmergedTree=true).assertExists();log("Real PATCH -> info updated title + success notice");capture("saved-info");result.put("normalDirtySave",true)
  }
  role("feed-owner"){
   open("22222222-2222-4222-8222-222222222222");compose.onNodeWithContentDescription("Описание").performScrollTo().performTextReplacement("Мои заметки сохраняются при сверке");f.device.pressBack();compose.onNodeWithTag("settings-save").performClick();f.waitText("Встреча изменилась");capture("conflict-notice");compose.onNodeWithTag("settings-reload").performClick();f.waitText("Продолжить с моими правками");f.waitText("Встреча с другого устройства");capture("conflict-review");f.device.pressBack();f.waitText("Встреча изменилась");compose.onNodeWithTag("settings-reload").performClick();f.waitText("Продолжить с моими правками");compose.waitUntil(5000){!compose.onNodeWithText("Продолжить с моими правками").fetchSemanticsNode().config.contains(SemanticsProperties.Disabled)};compose.onNodeWithText("Продолжить с моими правками").performClick();f.waitTag("settings-save");compose.onNodeWithContentDescription("Описание").assertTextContains("Мои заметки сохраняются при сверке");compose.onNodeWithContentDescription("Название").assertTextContains("Встреча с другого устройства");log("Real409 -> review latest facts -> Back -> review/resume rebases untouched title and retains local description");capture("conflict-resumed");compose.onNodeWithTag("settings-save").performClick();f.waitTag("meeting-information");f.waitText("Изменения сохранены");log("Rebased real PATCH -> info success");capture("conflict-saved");result.put("conflictReview",true)
  }
  result.put("status","observed-pass")
 }catch(e:Throwable){result.put("status","failed").put("error",e.toString());throw e}finally{f.shell("wm size reset");File(out,"result.json").writeText(result.put("actions",actions).put("finishedAt",Instant.now().toString()).toString(2))}}
 @Test fun saveConflictTail(){try{
 role("cover-edit"){open("c0fe0000-0000-4000-8000-000000000100");compose.onNodeWithContentDescription("Название").performScrollTo().performTextReplacement("Встреча после правки");hideKeyboard();compose.onNodeWithTag("settings-save").performClick();f.waitTag("meeting-information");f.waitText("Изменения сохранены");compose.onNode(hasText("Встреча после правки") and hasAnyAncestor(hasTestTag("meeting-information")),useUnmergedTree=true).assertExists();log("Real PATCH -> updated info heading + success notice");capture("saved-info");result.put("normalSave",true)}
 role("feed-owner"){open("22222222-2222-4222-8222-222222222222");compose.onNodeWithContentDescription("Описание").performScrollTo().performTextReplacement("Мои заметки сохраняются при сверке");hideKeyboard();compose.onNodeWithTag("settings-save").performClick();f.waitText("Встреча изменилась");capture("conflict-notice");compose.onNodeWithTag("settings-reload").performClick();f.waitText("Продолжить с моими правками");f.waitText("Встреча с другого устройства");capture("conflict-review");f.device.pressBack();f.waitText("Встреча изменилась");compose.onNodeWithTag("settings-reload").performClick();f.waitText("Продолжить с моими правками");compose.waitUntil(5000){!compose.onNodeWithText("Продолжить с моими правками").fetchSemanticsNode().config.contains(SemanticsProperties.Disabled)};compose.onNodeWithText("Продолжить с моими правками").performClick();f.waitTag("settings-save");compose.onNodeWithContentDescription("Описание").assertTextContains("Мои заметки сохраняются при сверке");compose.onNodeWithContentDescription("Название").assertTextContains("Встреча с другого устройства");log("Real409 -> review latest -> Back -> resume retains own description/rebases untouched title");capture("conflict-resumed");compose.onNodeWithTag("settings-save").performClick();f.waitTag("meeting-information");f.waitText("Изменения сохранены");log("Rebased PATCH -> info success");capture("conflict-saved");result.put("conflictReview",true)}
 result.put("status","observed-pass")
 }catch(e:Throwable){result.put("status","failed").put("error",e.toString());throw e}finally{File(out,"save-conflict-tail-result.json").writeText(result.put("actions",actions).put("at",Instant.now().toString()).toString(2))}}

 @Test fun conflictOnly(){try{val api=ChatReadLiveApi(f.context);val id="22222222-2222-4222-8222-222222222222";role("feed-owner"){open(id);compose.onNodeWithContentDescription("Описание").performScrollTo().performTextReplacement("Новая локальная правка для сверки");hideKeyboard();val current=api.request("invite-owner","meetings/$id");api.request("invite-owner","meetings/$id","PATCH",JSONObject().put("expected_revision",current.getString("revision")).put("title","Встреча с другого устройства"));log("Real authenticated concurrent PATCH after editor opened; stale UI revision preserved");compose.onNodeWithTag("settings-save").performClick();f.waitText("Встреча изменилась");capture("conflict-notice");compose.onNodeWithTag("settings-reload").performClick();f.waitText("Продолжить с моими правками");f.waitText("Встреча с другого устройства");capture("conflict-review");f.device.pressBack();f.waitText("Встреча изменилась");compose.onNodeWithTag("settings-reload").performClick();f.waitText("Продолжить с моими правками");compose.waitUntil(5000){!compose.onNodeWithText("Продолжить с моими правками").fetchSemanticsNode().config.contains(SemanticsProperties.Disabled)};compose.onNodeWithText("Продолжить с моими правками").performClick();f.waitTag("settings-save");compose.onNodeWithContentDescription("Описание").assertTextContains("Новая локальная правка для сверки");compose.onNodeWithContentDescription("Название").assertTextContains("Встреча с другого устройства");log("409 review -> Back -> resume retained local description, rebased untouched title");capture("conflict-resumed");compose.onNodeWithTag("settings-save").performClick();f.waitTag("meeting-information");f.waitText("Изменения сохранены");log("Real rebased PATCH -> updated info + success notice");capture("conflict-saved");File(out,"api-after-conflict.json").writeText(api.request("invite-owner","meetings/$id").toString(2));result.put("status","observed-pass")}}catch(e:Throwable){result.put("status","failed").put("error",e.toString());throw e}finally{File(out,"conflict-only-result.json").writeText(result.put("actions",actions).put("at",Instant.now().toString()).toString(2))}}

}
